#!/usr/bin/env node

/**
 * Bulk Create Android Subscriptions Script
 *
 * Creates subscription products in Google Play from a JSON file
 * generated by generate-product-ids.js
 *
 * Usage:
 *   node bulk-create-subscriptions-android.js <json-file-path> --package <package-name> [--dry-run]
 *   npm run bulk-create-subs-android -- product-ids.json --package com.example.app
 *   npm run bulk-create-subs-android -- product-ids.json --package com.example.app --dry-run
 */

require('dotenv').config();
const fs = require('fs');
const path = require('path');
const googlePlayClient = require('./src/services/googleplay-client');
const { DURATION_MAPPING } = require('./src/config/googleplay');
const logger = require('./src/utils/logger');

/**
 * Convert App Store period to Google Play ISO 8601 billing period
 * @param {string} duration - App Store period (e.g., "ONE_MONTH", "ONE_YEAR")
 * @returns {string} ISO 8601 duration (e.g., "P1M", "P1Y")
 */
function convertDuration(duration) {
  const normalized = duration.toUpperCase().trim();
  const mapped = DURATION_MAPPING[normalized];

  if (!mapped) {
    console.warn(`    [WARN] Unknown duration "${duration}", defaulting to P1M`);
    return 'P1M';
  }

  return mapped;
}

/**
 * Convert USD price string to Google Play Money format
 * @param {string} priceStr - Price string (e.g., "4.99")
 * @returns {object} Google Play Money object
 */
function convertPrice(priceStr) {
  if (!priceStr) return null;

  const price = parseFloat(priceStr);
  if (isNaN(price)) return null;

  const units = Math.floor(price).toString();
  const nanos = Math.round((price - Math.floor(price)) * 1e9);

  return {
    currencyCode: 'USD',
    units,
    nanos
  };
}

/**
 * Display help message
 */
function showHelp() {
  console.log(`
Bulk Create Android Subscriptions from JSON

Usage:
  node bulk-create-subscriptions-android.js <json-file-path> --package <package-name> [options]
  npm run bulk-create-subs-android -- <json-file-path> --package <package-name> [options]

Arguments:
  json-file-path    Path to the JSON file (output from generate-product-ids.js)

Options:
  --package <name>      Android package name (application ID) [required]
  --dry-run             Preview what would be created without making changes
  --activate-existing   Activate base plans for existing subscriptions that are in DRAFT state
  --help, -h            Show this help message

Examples:
  node bulk-create-subscriptions-android.js product-ids.json --package com.example.app
  node bulk-create-subscriptions-android.js product-ids.json --package com.example.app --dry-run
  node bulk-create-subscriptions-android.js product-ids.json --package com.example.app --activate-existing
  node bulk-create-subscriptions-android.js product-ids.json --package com.example.app --activate-existing --dry-run

Process:
  1. Reads the JSON file with subscription data
  2. Fetches existing subscriptions from Google Play
  3. Creates subscriptions with a base plan for each entry
  4. Reports success/failure for each operation

Input JSON format (from generate-product-ids.js):
  {
    "subscriptionGroups": [
      {
        "groupName": "Group Name",
        "subscriptions": [
          {
            "productId": "com.example.sub.monthly",
            "referenceName": "Monthly Plan",
            "duration": "ONE_MONTH",
            "price": "4.99"
          }
        ]
      }
    ]
  }
`);
}

/**
 * Fetch converted regional prices from Google Play for a USD price
 * @param {string} packageName - Android package name
 * @param {object} usdPrice - USD Money object
 * @returns {object} { regionalPrices, otherRegionsPrice }
 */
async function getRegionalPrices(packageName, usdPrice) {
  const result = await googlePlayClient.convertRegionPrices(packageName, usdPrice);

  const convertedRegionPrices = result.convertedRegionPrices || {};
  const convertedOtherRegionsPrice = result.convertedOtherRegionsPrice || null;
  const regionsVersion = result.regionVersion?.version || null;

  return { convertedRegionPrices, convertedOtherRegionsPrice, regionsVersion };
}

/**
 * Build Google Play subscription request body with all regional prices
 * @param {object} sub - Subscription data from JSON
 * @param {string} basePlanDuration - ISO 8601 duration
 * @param {object} convertedRegionPrices - Map of region code to converted price
 * @param {object} convertedOtherRegionsPrice - USD/EUR prices for other regions
 * @returns {object} Google Play subscription request body
 */
function buildSubscriptionBody(sub, basePlanDuration, convertedRegionPrices, convertedOtherRegionsPrice) {
  const basePlanId = sub.productId.replace(/\./g, '-');

  const body = {
    productId: sub.productId,
    listings: [
      {
        languageCode: 'en-US',
        title: sub.displayName || sub.referenceName || sub.name,
        description: sub.description || sub.referenceName || sub.name
      }
    ],
    basePlans: [
      {
        basePlanId: basePlanId,
        state: 'DRAFT',
        autoRenewingBasePlanType: {
          billingPeriodDuration: basePlanDuration,
          gracePeriodDuration: 'P14D',
          resubscribeState: 'RESUBSCRIBE_STATE_ACTIVE'
        },
        regionalConfigs: [],
        offerTags: []
      }
    ]
  };

  // Enable all regions with converted local currency prices
  for (const [regionCode, priceData] of Object.entries(convertedRegionPrices)) {
    body.basePlans[0].regionalConfigs.push({
      regionCode,
      newSubscriberAvailability: true,
      price: priceData.price || priceData
    });
  }

  // Enable future regions Google may add
  if (convertedOtherRegionsPrice) {
    body.basePlans[0].otherRegionsConfig = {
      usdPrice: convertedOtherRegionsPrice.usdPrice,
      eurPrice: convertedOtherRegionsPrice.eurPrice,
      newSubscriberAvailability: true
    };
  }

  return { body, basePlanId };
}

/**
 * Create a single subscription on Google Play
 * @param {string} packageName - Android package name
 * @param {object} sub - Subscription data
 * @param {boolean} dryRun - If true, don't actually create
 * @returns {object} Result
 */
async function createSubscription(packageName, sub, dryRun, regionalPricesCache) {
  const duration = convertDuration(sub.duration || 'ONE_MONTH');
  const usdPrice = convertPrice(sub.price);

  if (dryRun) {
    console.log(`    [DRY-RUN] Would create: ${sub.productId}`);
    console.log(`              Name: ${sub.referenceName || sub.name}`);
    console.log(`              Period: ${duration}`);
    console.log(`              Base Plan ID: ${sub.productId.replace(/\./g, '-')}`);
    console.log(`              Price USD: ${sub.price || 'N/A'}`);
    return { success: true, dryRun: true };
  }

  try {
    // Use cached regional prices or fetch new ones for this price point
    const priceKey = sub.price;
    let convertedRegionPrices, convertedOtherRegionsPrice, regionsVersion;

    if (regionalPricesCache[priceKey]) {
      ({ convertedRegionPrices, convertedOtherRegionsPrice, regionsVersion } = regionalPricesCache[priceKey]);
    } else {
      console.log(`    [INFO] Fetching regional prices for USD ${sub.price}...`);
      ({ convertedRegionPrices, convertedOtherRegionsPrice, regionsVersion } = await getRegionalPrices(packageName, usdPrice));
      regionalPricesCache[priceKey] = { convertedRegionPrices, convertedOtherRegionsPrice, regionsVersion };
      console.log(`    [INFO] Got prices for ${Object.keys(convertedRegionPrices).length} regions (regionsVersion: ${regionsVersion})`);
    }

    const { body, basePlanId } = buildSubscriptionBody(sub, duration, convertedRegionPrices, convertedOtherRegionsPrice);

    const response = await googlePlayClient.createSubscription(
      packageName,
      sub.productId,
      body,
      regionsVersion
    );
    console.log(`    [SUCCESS] Created: ${sub.productId} (base plan: ${basePlanId}, regions: ${Object.keys(convertedRegionPrices).length})`);
    return { success: true, data: response };
  } catch (error) {
    console.error(`    [ERROR] Failed to create ${sub.productId}: ${error.message}`);
    return { success: false, error: error.message };
  }
}

/**
 * Activate base plans for an existing subscription that are in DRAFT state
 * @param {string} packageName - Android package name
 * @param {string} productId - Subscription product ID
 * @param {object} existingSub - Existing subscription object from Google Play
 * @param {boolean} dryRun - If true, don't actually activate
 * @returns {boolean} True if any base plans were activated
 */
async function activateExistingBasePlans(packageName, productId, existingSub, dryRun) {
  const basePlans = existingSub?.basePlans || [];

  if (basePlans.length === 0) {
    console.log(`    [SKIP] ${productId} - no base plans found`);
    return false;
  }

  const draftPlans = basePlans.filter(bp => bp.state === 'DRAFT');

  if (draftPlans.length === 0) {
    console.log(`    [ACTIVE] ${productId} - all base plans already active`);
    return false;
  }

  let activatedAny = false;

  for (const bp of draftPlans) {
    const basePlanId = bp.basePlanId;

    if (dryRun) {
      console.log(`    [DRY-RUN] Would activate base plan: ${basePlanId} for ${productId}`);
      activatedAny = true;
      continue;
    }

    try {
      await googlePlayClient.activateBasePlan(packageName, productId, basePlanId);
      console.log(`    [ACTIVATED] ${productId} base plan: ${basePlanId}`);
      activatedAny = true;
    } catch (error) {
      console.error(`    [ERROR] Failed to activate ${productId} base plan ${basePlanId}: ${error.message}`);
    }
  }

  return activatedAny;
}

/**
 * Main function
 */
async function main() {
  const args = process.argv.slice(2);

  if (args.includes('--help') || args.includes('-h')) {
    showHelp();
    process.exit(0);
  }

  const dryRun = args.includes('--dry-run');
  const activateExisting = args.includes('--activate-existing');

  // Parse --package argument
  const packageIdx = args.indexOf('--package');
  const packageName = packageIdx !== -1 ? args[packageIdx + 1] : null;

  const jsonPath = args.find(arg => !arg.startsWith('--') && arg !== packageName);

  if (!jsonPath) {
    console.error('Error: JSON file path is required\n');
    showHelp();
    process.exit(1);
  }

  if (!packageName) {
    console.error('Error: --package <package-name> is required\n');
    showHelp();
    process.exit(1);
  }

  if (!fs.existsSync(jsonPath)) {
    console.error(`Error: File not found: ${jsonPath}`);
    process.exit(1);
  }

  console.log('='.repeat(70));
  console.log('Bulk Create Android Subscriptions (Google Play)');
  console.log('='.repeat(70));

  if (dryRun) {
    console.log('\n[DRY-RUN MODE] No changes will be made\n');
  }

  try {
    // Read JSON file
    const data = JSON.parse(fs.readFileSync(jsonPath, 'utf-8'));
    console.log(`\nSource file: ${jsonPath}`);
    console.log(`Package: ${packageName}`);
    console.log(`Subscription Groups: ${data.subscriptionGroups.length}`);
    console.log(`Total Subscriptions: ${data.totalCount}`);

    // Fetch existing subscriptions
    let existingProductIds = [];
    const existingSubscriptionMap = new Map();
    if (!dryRun) {
      console.log('\nFetching existing subscriptions from Google Play...');
      try {
        const existing = await googlePlayClient.getSubscriptions(packageName);
        const subs = existing.subscriptions || [];
        existingProductIds = subs.map(s => s.productId);
        subs.forEach(s => existingSubscriptionMap.set(s.productId, s));
        console.log(`Existing Subscriptions: ${existingProductIds.length}`);
      } catch (error) {
        console.warn(`[WARN] Could not fetch existing subscriptions: ${error.message}`);
        console.warn('Proceeding without duplicate check.\n');
      }
    }

    // Track results
    const results = {
      created: 0,
      activated: 0,
      existing: 0,
      failed: 0
    };

    // Cache for converted regional prices (keyed by USD price string)
    const regionalPricesCache = {};

    // Process each subscription group
    console.log('\n' + '-'.repeat(70));
    console.log('Processing Subscriptions');
    console.log('-'.repeat(70));

    for (const group of data.subscriptionGroups) {
      console.log(`\nGroup: ${group.groupName}`);

      for (const sub of group.subscriptions) {
        // Check if already exists
        if (existingProductIds.includes(sub.productId)) {
          if (activateExisting) {
            const existingSub = existingSubscriptionMap.get(sub.productId);
            const activatedAny = await activateExistingBasePlans(packageName, sub.productId, existingSub, dryRun);
            if (activatedAny) {
              results.activated++;
            } else {
              results.existing++;
            }
          } else {
            console.log(`    [EXISTS] ${sub.productId}`);
            results.existing++;
          }
          continue;
        }

        const result = await createSubscription(packageName, sub, dryRun, regionalPricesCache);

        if (result.success) {
          results.created++;
          existingProductIds.push(sub.productId);
        } else {
          results.failed++;
        }

        // Rate limit delay
        if (!dryRun) {
          await new Promise(resolve => setTimeout(resolve, 500));
        }
      }
    }

    // Print summary
    console.log('\n' + '='.repeat(70));
    console.log('Summary');
    console.log('='.repeat(70));
    console.log(`\nSubscriptions:`);
    console.log(`  Created: ${results.created}`);
    console.log(`  Activated: ${results.activated}`);
    console.log(`  Already Existed: ${results.existing}`);
    console.log(`  Failed: ${results.failed}`);

    if (dryRun) {
      console.log('\n[DRY-RUN] No changes were made. Remove --dry-run to execute.');
    }

    if (results.failed > 0) {
      process.exit(1);
    }

  } catch (error) {
    console.error(`\nFatal error: ${error.message}`);
    logger.error('Bulk create Android subscriptions failed:', error);
    process.exit(1);
  }
}

main();
